<body>
<div id="hint">N — toggle day / night &nbsp;·&nbsp; drag to orbit, wheel to zoom</div>
<script type="module">
import * as THREE from './three.module.js';

// ---------- world parameters ----------
const N = 72;                 // map size in voxels
const WATER = 4;              // water surface level
const cell = 1;               // voxel size

// deterministic RNG so the layout is stable
let seed = 1337;
const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;

// smooth value noise on a coarse lattice
const lat = [];
for (let i = 0; i < 10; i++) { lat.push([]); for (let j = 0; j < 10; j++) lat[i].push(rnd()); }
const sm = t => t * t * (3 - 2 * t);
function noise(x, z) {
  const gx = x / 14, gz = z / 14;
  const x0 = Math.floor(gx), z0 = Math.floor(gz);
  const fx = sm(gx - x0), fz = sm(gz - z0);
  const g = (i, j) => lat[(i % 9 + 9) % 9][(j % 9 + 9) % 9];
  return g(x0, z0) * (1 - fx) * (1 - fz) + g(x0 + 1, z0) * fx * (1 - fz)
       + g(x0, z0 + 1) * (1 - fx) * fz + g(x0 + 1, z0 + 1) * fx * fz;
}

// river path: winds from z=0 edge to z=N-1 edge around x≈N*0.62
const riverX = z => N * 0.60 + Math.sin(z * 0.11) * 9 + Math.sin(z * 0.31 + 1.7) * 3.5;

// ---------- height field ----------
const H = new Int16Array(N * N);
const heightAt = (x, z) => {
  let h = 6 + noise(x, z) * 13;                       // rolling hills
  h += noise(x + 40, z + 40) * 4;                     // detail
  const d = Math.abs(x - riverX(z));                  // carve the valley
  if (d < 6) h = Math.min(h, WATER - 1.2 + d * 0.55);
  return Math.max(1, Math.floor(h));
};
for (let z = 0; z < N; z++) for (let x = 0; x < N; x++) H[z * N + x] = heightAt(x, z);

// ---------- village layout ----------
// plateau near the west side, away from the river
const cx = 24, cz = 34;                               // village centre
const plots = [];
const footprints = [
  { w: 7, d: 7 }, { w: 5, d: 6 }, { w: 6, d: 4 }, { w: 5, d: 5 },
  { w: 4, d: 7 }, { w: 6, d: 6 }, { w: 5, d: 4 }, { w: 4, d: 4 },
  { w: 7, d: 5 }, { w: 4, d: 6 }, { w: 6, d: 5 }, { w: 5, d: 7 },
  { w: 4, d: 5 }, { w: 6, d: 7 },
];
let tries = 0;
while (plots.length < 14 && tries++ < 900) {
  const f = footprints[plots.length % footprints.length];
  const px = Math.round(cx - 14 + rnd() * 28), pz = Math.round(cz - 14 + rnd() * 28);
  if (Math.abs(px - riverX(pz)) < 9) continue;        // keep off the river
  let ok = true;
  for (const p of plots) {
    if (Math.abs(px - p.x) < (f.w + p.w) / 2 + 3 && Math.abs(pz - p.z) < (f.d + p.d) / 2 + 3) { ok = false; break; }
  }
  if (!ok) continue;
  plots.push({ x: px, z: pz, w: f.w, d: f.d, style: plots.length % 3, r: plots.length % 4 });
}

// flatten terrain under each plot; village ground level
let vsum = 0; for (const p of plots) vsum += H[p.z * N + p.x];
const GY = Math.round(vsum / plots.length);
for (const p of plots)
  for (let dz = -p.d; dz <= p.d + 1; dz++) for (let dx = -p.w; dx <= p.w + 1; dx++) {
    const x = p.x + dx, z = p.z + dz;
    if (x < 0 || z < 0 || x >= N || z >= N) continue;
    const edge = Math.max(Math.abs(dx / (p.w + 1)), Math.abs(dz / (p.d + 1)));
    const t = Math.min(1, Math.max(0, (edge - 0.75) / 0.25));   // blend at rim
    const target = GY + (edge < 0.75 ? 0 : Math.round((H[z * N + x] - GY) * t));
    H[z * N + x] = Math.round(target + (GY - target) * (1 - t));
  }

// stone path: connect plots in sequence + a spine through the centre
const pathCells = new Set();
const addSeg = (x0, z0, x1, z1) => {
  let x = x0, z = z0;
  while (x !== x1) { pathCells.add(z * N + x); x += Math.sign(x1 - x); }
  while (z !== z1) { pathCells.add(z * N + x); z += Math.sign(z1 - z); }
  pathCells.add(z1 * N + x1);
};
for (let i = 1; i < plots.length; i++) addSeg(plots[i - 1].x, plots[i - 1].z, plots[i].x, plots[i].z);
addSeg(plots[0].x, plots[0].z, cx, cz);
addSeg(cx, cz, plots[plots.length - 1].x, plots[plots.length - 1].z);

// ---------- geometry: one merged box per material, instanced ----------
const geo = new THREE.BoxGeometry(cell, cell, cell);
// slight inset so voxel seams read as crisp voxel-art grid
const pos = geo.attributes.position;
for (let i = 0; i < pos.count; i++) {
  pos.setXYZ(i, pos.getX(i) * 0.98 + (pos.getX(i) > 0 ? 0.01 : -0.01),
             pos.getY(i) * 0.98, pos.getZ(i) * 0.98);
}

const mats = {
  grass:  new THREE.MeshLambertMaterial({ color: 0x6fae4a }),
  grassB: new THREE.MeshLambertMaterial({ color: 0x5d9a3e }),
  dirt:   new THREE.MeshLambertMaterial({ color: 0x8a6a48 }),
  stone:  new THREE.MeshLambertMaterial({ color: 0x8f8f96 }),
  sand:   new THREE.MeshLambertMaterial({ color: 0xdcc98f }),
  water:  new THREE.MeshLambertMaterial({ color: 0x3f7fb5, transparent: true, opacity: 0.85 }),
  path:   new THREE.MeshLambertMaterial({ color: 0xb0a894 }),
  trunk:  new THREE.MeshLambertMaterial({ color: 0x6b4a2f }),
  leaf:   new THREE.MeshLambertMaterial({ color: 0x4c7c36 }),
  leafD:  new THREE.MeshLambertMaterial({ color: 0x3e6a2c }),
  wallA:  new THREE.MeshLambertMaterial({ color: 0xe8dcc3 }),
  wallB:  new THREE.MeshLambertMaterial({ color: 0xd9b8a0 }),
  wallC:  new THREE.MeshLambertMaterial({ color: 0xc9d2d8 }),
  roofT:  new THREE.MeshLambertMaterial({ color: 0xb5563e }),   // terracotta
  roofS:  new THREE.MeshLambertMaterial({ color: 0x5c6470 }),   // slate
  roofG:  new THREE.MeshLambertMaterial({ color: 0x8a8a52 }),   // mossy
  roofB:  new THREE.MeshLambertMaterial({ color: 0x7a4a38 }),   // brown
  wood:   new THREE.MeshLambertMaterial({ color: 0x9c7a52 }),
  window: new THREE.MeshLambertMaterial({ color: 0x9fc4d8, emissive: 0x000000 }),
};

// bucket collector: key -> list of [x,y,z]
const buckets = {};
const put = (k, x, y, z) => (buckets[k] ??= []).push(x, y, z);

// ---------- build terrain columns ----------
const treeSpots = [];
for (let z = 0; z < N; z++) for (let x = 0; x < N; x++) {
  const h = H[z * N + x];
  const nearRiver = Math.abs(x - riverX(z));
  let top = 'grass';
  if (h <= WATER + 1) top = 'sand';
  if (h <= WATER - 1) { put('water', x, WATER, z); top = 'sand'; }
  if (pathCells.has(z * N + x) && h > WATER) { put('path', x, h, z); top = 'pathTop'; }
  put(top === 'pathTop' ? 'grass' : top, x, h, z);       // surface block
  // subsurface
  put(h - 1 >= 0 ? (h <= WATER + 1 ? 'sand' : 'dirt') : 'stone', x, h - 1, z);
  for (let y = Math.max(0, h - 4); y < h - 1; y++) put('stone', x, y, z);
  if (h < WATER) for (let y = h; y <= WATER; y++) put('water', x, y, z); // fill basin

  // trees on grass, away from village & river & path
  if (top === 'grass' && h > WATER + 1 && rnd() < 0.045) {
    let near = false;
    for (const p of plots) if (Math.abs(x - p.x) < p.w + 4 && Math.abs(z - p.z) < p.d + 4) near = true;
    if (Math.abs(x - riverX(z)) < 5) near = true;
    if (pathCells.has(z * N + x)) near = true;
    if (!near) treeSpots.push([x, h, z]);
  }
}

// ---------- buildings ----------
const winCells = [];   // window voxel positions for night glow
plots.forEach((p, i) => {
  const gy = GY;
  const wallMat = ['wallA', 'wallB', 'wallC'][p.style];
  const roofMat = ['roofT', 'roofS', 'roofG', 'roofB'][p.r];
  const x0 = p.x - (p.w >> 1), x1 = x0 + p.w - 1;
  const z0 = p.z - (p.d >> 1), z1 = z0 + p.d - 1;
  const floors = p.style === 0 ? 2 : p.style === 1 ? 1 : 3;   // 3 visibly different designs
  const fh = floors * 3 + 1;
  const H2 = gy + fh;

  // walls (hollow), corner posts in wood
  for (let y = gy + 1; y <= H2; y++)
    for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
      const edge = x === x0 || x === x1 || z === z0 || z === z1;
      if (!edge) continue;
      const corner = (x === x0 || x === x1) && (z === z0 || z === z1);
      const isWin = y % 3 === 0 && y < H2 && !corner &&
        ((x === x0 || x === x1) ? (z - z0) % 2 === 1 : (x - x0) % 2 === 1);
      if (isWin) { put('window', x, y, z); winCells.push(x, y, z); }
      else put(corner && y > gy + 1 ? 'wood' : wallMat, x, y, z);
    }
  // floor slab + door on south side
  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) put('wood', x, gy, z);
  put('wood', Math.floor((x0 + x1) / 2), gy + 1, z1);
  put('wood', Math.floor((x0 + x1) / 2), gy + 2, z1);

  // roofs: style 0 = gable, style 1 = pyramid, style 2 = flat parapet
  const rw = x1 - x0 + 1, rd = z1 - z0 + 1;
  if (p.style === 0) {
    for (let s = 0; s <= Math.ceil(rw / 2); s++) {
      const y = H2 + s;
      for (let z = z0 - 1; z <= z1 + 1; z++) {
        put(roofMat, x0 + s - 1, y, z); put(roofMat, x1 - s + 1, y, z);
      }
      if (x0 + s > x1 - s) break;
    }
    // gable end triangles filled with wall material
    for (let s = 0; s < Math.ceil(rw / 2); s++) {
      const y = H2 + s + 1;
      put(wallMat, x0 + s, y, z0); put(wallMat, x0 + s, y, z1);
      put(wallMat, x1 - s, y, z0); put(wallMat, x1 - s, y, z1);
    }
  } else if (p.style === 1) {
    let s = 0;
    while (x0 + s <= x1 && z0 + s <= z1) {
      const y = H2 + s;
      for (let x = x0 + s; x <= x1 - s; x++) { put(roofMat, x, y, z0 + s); put(roofMat, x, y, z1 - s); }
      for (let z = z0 + s; z <= z1 - s; z++) { put(roofMat, x0 + s, y, z); put(roofMat, x1 - s, y, z); }
      s++;
    }
  } else {
    for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++)
      put(roofMat, x, H2 + 1, z);
    for (let x = x0; x <= x1; x++) { put(roofMat, x, H2 + 2, z0); put(roofMat, x, H2 + 2, z1); }
    for (let z = z0; z <= z1; z++) { put(roofMat, x0, H2 + 2, z); put(roofMat, x1, H2 + 2, z); }
  }
  // chimney on some houses
  if (i % 3 === 0) {
    const chx = x0 + 1, chz = z0 + 1;
    for (let y = gy + 1; y <= H2 + 4; y++) put('stone', chx, y, chz);
  }
});

// ---------- trees ----------
for (const [x, h, z] of treeSpots) {
  const th = 3 + Math.floor(rnd() * 3);
  for (let y = h + 1; y <= h + th; y++) put('trunk', x, y, z);
  const ty = h + th;
  const r = rnd() < 0.5 ? 2 : 2;
  for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) for (let dy = 0; dy <= 2; dy++) {
    if (Math.abs(dx) + Math.abs(dz) + dy > r + 2) continue;
    if (dy === 0 && Math.abs(dx) === 2 && Math.abs(dz) === 2) continue;
    put(rnd() < 0.3 ? 'leafD' : 'leaf', x + dx, ty + dy, z + dz);
  }
  put('leaf', x, ty + 3, z);
}

// ---------- instanced meshes ----------
const world = new THREE.Group();
scene.add(world);   // (scene created below — hoisted use is fine since this runs later? no...)
