  while (z !== z1) { pathCells.add(z * N + x); z += Math.sign(z1 - z); }
  pathCells.add(z1 * N + x1);
};
for (let i = 1; i < plots.length; i++) addSeg(plots[i - 1].x, plots[i - 1].z, plots[i].x, plots[i].z);
addSeg(plots[0].x, plots[0].z, cx, cz);
addSeg(cx, cz, plots[plots.length - 1].x, plots[plots.length - 1].z);

