  const floors = [2, 1, 3][p.style];
  const H2 = gy + floors * 3 + 1;

  for (let y = gy + 1; y <= H2; y++)
    for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
      const edge = x === x0 || x === x1 || z === z0 || z === z1;
      if (!edge) continue;
      const corner = (x === x0 || x === x1) && (z === z0 || z === z1);
      const isWin = y % 3 === 0 && y < H2 && !corner &&
        ((x === x0 || x === x1) ? (z - z0) % 2 === 1 : (x - x0) % 2 === 1);
      if (isWin) put('window', x, y, z);
      else put(corner && y > gy + 1 ? 'wood' : wallMat, x, y, z);
    }
  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) put('wood', x, gy, z);
  const dxm = Math.floor((x0 + x1) / 2);
  put('wood', dxm, gy + 1, z1); put('wood', dxm, gy + 2, z1);

  // roofs
  if (p.style === 0) {                       // gable
    const half = Math.ceil((x1 - x0 + 1) / 2);
    for (let s = 0; s <= half; s++) {
      const y = H2 + s;
      for (let z = z0 - 1; z <= z1 + 1; z++) {
