// ================= hand-rolled orbit camera =================
const target = new THREE.Vector3(cx + ox, GY + 2, cz + oz);
let az = Math.PI * 0.25, pol = 1.05, dist = 96;
let dragging = false, lx = 0, ly = 0;
const dom = renderer.domElement;
dom.addEventListener('pointerdown', e => { dragging = true; lx = e.clientX; ly = e.clientY; });
addEventListener('pointerup', () => dragging = false);
addEventListener('pointermove', e => {
  if (!dragging) return;
  az -= (e.clientX - lx) * 0.005;
  pol = Math.min(1.45, Math.max(0.35, pol - (e.clientY - ly) * 0.004));
  lx = e.clientX; ly = e.clientY;
});
dom.addEventListener('wheel', e => {
  dist = Math.min(160, Math.max(45, dist + e.deltaY * 0.05));
  e.preventDefault();
}, { passive: false });

function updateCamera() {
  if (!dragging) az += 0.0016;                       // slow auto-rotation
  const r = dist * Math.sin(pol);
  camera.position.set(
    target.x + r * Math.sin(az),
    target.y + dist * Math.cos(pol),
    target.z + r * Math.cos(az));
  camera.lookAt(target);
}

// ================= animate =================
const clock = new THREE.Clock();
function loop() {
  requestAnimationFrame(loop);
  const t = clock.getElapsedTime();
  updateCamera();
  if (waterMesh) waterMesh.position.y = Math.sin(t * 1.4) * 0.06;   // gentle water shimmer
  renderer.render(scene, camera);
}
loop();

addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
